import{_ as t}from"./chunks/icon.B7gRmRZx.js";import{_ as r,a as n,b as s,c as i,d as o,e as a,f as d,g as u,h as l,i as g,j as c,k as p,l as h}from"./chunks/0.1.12-193-neustart-de.DMY_PLph.js";import{_ as m,o as b,c as k,a3 as f}from"./chunks/framework.BlfGB29P.js";const D=JSON.parse('{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.98 · Aufbewahrung der Runtime-Protokolle","frontmatter":{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.98 · Aufbewahrung der Runtime-Protokolle"},"headers":[],"relativePath":"projects/logic-studio/index.md","filePath":"projects/logic-studio/index.md","lastUpdated":1795453707000}'),A={name:"projects/logic-studio/index.md"};function S(P,e,w,T,y,H){return b(),k("div",null,[...e[0]||(e[0]=[f('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+t+'" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – öffentliches Testupdate, 8. November 2026.</strong> Oberfläche und Dokumentation sind jetzt <strong>DE/EN/FR</strong>. Logic Studio ist eine eigene HA-App für grafische Funktionspläne, unabhängig von Grafik Visual Studio und Blocks for HA. Die React-Flow-Zeichenfläche mit eigenen Bausteinen, typgeprüften Verbindungen, Zoom und MiniMap bleibt erhalten; Bibliotheken und Lizenzen sind lokal enthalten.</p><div class="warning custom-block"><p class="custom-block-title">Testversion</p><p>Zuerst auf einem Testsystem installieren und vorher ein vollständiges Backup erstellen. Native Detailoptionen werden zunächst als JSON bearbeitet. Die App schreibt keine Automationen oder Skripte in HA zurück und schaltet keine Geräte. Erzeugte Ausgaben immer prüfen und selbst in HA installieren.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">GitHub-Testrelease und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Quellcode im Sammel-Repository</a></p><h2 id="ha-logic-studio-pro" tabindex="-1">HA Logic Studio Pro <a class="header-anchor" href="#ha-logic-studio-pro" aria-label="Permalink to &quot;HA Logic Studio Pro&quot;">​</a></h2><p>HA Logic Studio Pro ist eine eigenständige Home-Assistant-App im UGSo-Sammelrepository. Sie baut auf Logic Studio auf und greift Erfahrungen aus der Arbeit mit ioBroker auf.</p><p><strong>Verfügbare Funktionen</strong></p><ul><li><strong>Funktionsplan:</strong> Bausteine verbinden, Signale an den Eingängen anzeigen und den Plan simulieren. Die Ausführung auf dem HA-Server kann auf Änderungen reagieren oder in einem festen Zyklus laufen.</li><li><strong>Regeln und Blocks A:</strong> Automationen visuell erstellen und als HA-YAML ausgeben.</li><li><strong>Blocks JS, JavaScript und TypeScript:</strong> Logik bearbeiten, mit simulierten Werten testen und auf dem HA-Server ausführen.</li><li><strong>HA-YAML:</strong> Automationen und Skripte bearbeiten, prüfen und exportieren.</li><li><strong>Projektverwaltung:</strong> Projekte und Ordner pro HA-Benutzer auf dem Server speichern.</li><li><strong>Sprachwahl:</strong> Die Editoren stehen auf Deutsch, Englisch und Französisch zur Verfügung.</li></ul><h3 id="ha-logic-studio-pro-0-1-121–0-1-140" tabindex="-1">HA Logic Studio Pro 0.1.121–0.1.140 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-121–0-1-140" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.121–0.1.140&quot;">​</a></h3><p><strong>0.1.130 · ioBroker-Adapterneustart beim Import erhalten</strong></p><p>Im Test mit einem echten Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> zeigte der importierte <code>control_instance</code>-Block <strong>admin.0 · Neustart</strong>. Der Hinweis direkt am Block nennt <code>hassio.app_restart</code> für eine HA-App und <code>homeassistant.reload_config_entry</code> für eine Integration. Play blockierte den Platzhalter. Der Test löste keinen Neustart aus.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.130" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.130 · GitHub / ZIP</a></p><p><strong>0.1.129 · Existenzprüfung mit berechneter ioBroker-ID</strong></p><p>Beim Play-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> lieferte der importierte Block <code>state_exists_var</code> für eine vorhandene HA-Entität <code>true</code> und für eine zugeordnete, fehlende Entität <code>false</code>. Bei fehlender Zuordnung meldete das Protokoll die berechnete ioBroker-ID. Der Hinweis zur Zuordnung war direkt am Block sichtbar.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.129" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.129 · GitHub / ZIP</a></p><p><strong>0.1.128 · Hinweis für ioBroker-Ablaufzeiten in Blocks JS</strong></p><p>Bei <code>control_ex</code> mit <code>expire</code> bleibt der Block mit seinen Eingaben als Platzhalter erhalten. ioBroker entfernt den gespeicherten Zustand nach Ablauf. Ein HA-Schalterhelfer behält seinen Ein/Aus-Zustand. Im Play-Test mit einem echten Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> erschien der <strong>Hinweis direkt am Block</strong>. Play wurde blockiert und der Helfer blieb aus.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.128" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.128 · GitHub / ZIP</a></p><p><strong>0.1.127 · Verzögertes Steuern mit berechneter ioBroker-ID</strong></p><p>Blocks JS übernimmt <code>control_ex</code> im Modus „steuere“ mit berechneter ID, booleschem Wert und berechneter Verzögerung. Im Play-Test mit einem echten ioBroker-Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> blieb der zugeordnete HA-Schalterhelfer nach rund vier Sekunden noch aus und war nach Ablauf der berechneten Verzögerung von <strong>15 Sekunden</strong> eingeschaltet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.127" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.127 · GitHub / ZIP</a></p><p><strong>0.1.126 · Verzögertes Aktualisieren mit berechneter ioBroker-ID</strong></p><p>Blocks JS übernimmt <code>control_ex</code> im Modus „aktualisiere“ mit berechneter ID und Verzögerung. Die ID wird ausdrücklich einem HA-Helfer zugeordnet. Beim Play-Test mit einem echten ioBroker-Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wechselte der Zahlenhelfer nach der berechneten Verzögerung von <strong>15 Sekunden</strong> von <strong>0</strong> auf <strong>42</strong>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.126" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.126 · GitHub / ZIP</a></p><p><strong>0.1.125 · ioBroker-Nachricht mit Antwort in Blocks JS</strong></p><p>Blocks JS übernimmt <code>sendto_custom</code> mit benannten Parametern und Antwortzweig. Beim Import lässt sich eine HA-Skriptaktion mit Rückgabedaten zuordnen. Im Play-Test mit einem echten ioBroker-Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> ergaben die Parameter <code>left: 17</code> und <code>right: 25</code> den Wert <strong>42</strong>. Der Antwortzweig las <code>result.total</code> und protokollierte <strong>42</strong>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.125" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.125 · GitHub / ZIP</a></p><p><strong>0.1.124 · Direkte ioBroker-Verknüpfung in Blocks JS</strong></p><p>Blocks JS übernimmt den ioBroker-Block <code>direct</code> mit getrennter Zuordnung für Quelle und Ziel sowie der Option „nur bei Änderung“. Beim Play-Test mit einem echten Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> schrieb der Quellwechsel von <strong>0</strong> auf <strong>53</strong> den Wert <strong>53</strong> in den Zielhelfer. Anschließend wurde das Ziel zur Kontrolle auf <strong>7</strong> gesetzt. Als sich nur ein Attribut der Quelle änderte und ihr Wert <strong>53</strong> blieb, behielt das Ziel den Wert <strong>7</strong>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.124" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.124 · GitHub / ZIP</a></p><p><strong>0.1.123 · Asynchroner Wertimport in Blocks JS</strong></p><p>Blocks JS übernimmt <code>get_value_async</code> mit HA-Entitätszuordnung und Antwortzweig. Der Block „Gelesener Wert“ gibt dort den ausgewählten Wert zurück. Im Play-Test mit einem echten ioBroker-Blockly-Export auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> las und protokollierte das Skript <strong>52</strong> und schrieb <strong>52</strong> in einen separat zugeordneten HA-Zahlenhelfer.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.123" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.123 · GitHub / ZIP</a></p><p><strong>0.1.122 · ioBroker-Datenpunkte als HA-Helfer</strong></p><p>Blocks JS importiert <code>createState</code> mit der Blockfolge zum Lesen und Aktualisieren. Im Importdialog kann man einen vorhandenen HA-Helfer zuordnen, einen neuen anlegen oder die Zuordnung später vornehmen.</p><p>Im Live-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> legte Blocks JS einen Zahlenhelfer mit Startwert <strong>17</strong> an. Das Skript las <strong>17</strong>, schrieb <strong>42</strong> und las nach dem Skriptneustart erneut <strong>42</strong>. Der echte ioBroker-Blockly-Export ergab denselben Arbeitsbereich. Die Zuordnung zu einem vorhandenen Helfer wurde damit in Chrome geprüft.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.122" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.122 · GitHub / ZIP</a></p><p><strong>0.1.121 · Kompakte Tab-Leiste und Alles speichern</strong></p><p>Jeder Tab bündelt Projektname, rotes Quadrat für ungespeicherte Änderungen und Schließen-Kreuz. Die blaue Linie zeigt den aktiven Tab.</p><p>Im Chrome-Test blieb <strong>Alles speichern</strong> bei einem geänderten Tab verborgen. Bei zwei geänderten Tabs erschien die Schaltfläche zwischen <strong>Speichern</strong> und <strong>Abbrechen</strong>. Nach einem Klick und erneutem Laden waren beide Änderungen erhalten. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.121" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.121 · GitHub / ZIP</a></p><h3 id="ha-logic-studio-pro-0-1-101–0-1-120" tabindex="-1">HA Logic Studio Pro 0.1.101–0.1.120 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-101–0-1-120" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.101–0.1.120&quot;">​</a></h3><p><strong>0.1.120 · Asynchrones Objektlesen und Alles speichern</strong></p><p>Blocks JS übernimmt <code>get_object_async</code> mit ausdrücklicher Zuordnung einer HA-Entität. Im Play-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> gab der Antwortzweig über <code>common.name</code> den Anzeigenamen <strong>Logic Studio Runtime Test</strong> aus.</p><p>Bei mehreren offenen Tabs erscheint <strong>Alles speichern</strong>. Die Schaltfläche speichert die Änderungen aller offenen Projekte gemeinsam. Ein rotes Quadrat markiert jeden Tab mit ungespeicherten Änderungen.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.120" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.120 · GitHub / ZIP</a></p><p><strong>0.1.119 · Import des ioBroker-Selektors</strong></p><p>Blocks JS übernimmt den ioBroker-Selektor <code>$()</code> als Listenblock. Der ursprüngliche Ausdruck bleibt am Block sichtbar. Die beim Import ausdrücklich zugeordneten HA-Entitäten werden als feste Liste gespeichert. Beim Play-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> gab die importierte Schleife <code>input_boolean.logic_studio_runtime_test</code> und <code>input_number.ugso_rules_080_level</code> jeweils einmal aus.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.119" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.119 · GitHub / ZIP</a></p><p><strong>0.1.118 · Import der ioBroker-Kategorie-Mitglieder</strong></p><p>Blocks JS übernimmt <code>get_enum_members</code> mit aktivierter Option „nur Zustände“. Beim Import wird die Kategorie einem HA-Bereich oder Label zugeordnet. Im Play-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> gab die importierte Schleife beide IDs des HA-Labels jeweils einmal aus. Im Protokoll standen <code>input_boolean.logic_studio_runtime_test</code> und <code>input_number.ugso_rules_080_level</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.118" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.118 · GitHub / ZIP</a></p><p><strong>0.1.117 · Import des ioBroker-Kategorieauslösers</strong></p><p>Blocks JS ordnet die Kategorie aus <code>onEnumMembers</code> beim Import einem HA-Bereich oder Label zu und speichert die dabei ermittelten Entitäten. Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurde ein Blockly-Export einem HA-Label mit zwei Testhelfern zugeordnet. Das laufende Skript protokollierte <code>input_boolean.logic_studio_runtime_test</code> mit <code>true</code> und <code>input_number.ugso_rules_080_level</code> mit <code>42.0</code>. Die Zustandsänderung von <code>counter.ugso_rules_080_count</code> außerhalb des Labels erzeugte keine Ausgabe.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.117" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.117 · GitHub / ZIP</a></p><p><strong>0.1.116 · Import des ioBroker-Logauslösers</strong></p><p>Blocks JS übernimmt <code>onLog</code> und die Datenblöcke für Meldungstext und Logstufe. Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurde ein echter ioBroker-Blockly-Export importiert. Beim manuell ausgelösten HA-Ereignis <code>system_log_event</code> mit <code>WARNING</code> protokollierte das laufende Skript die Meldung und <code>warn</code>. Das Kontrollereignis mit <code>ERROR</code> erzeugte keine Ausgabe. Für automatisch erzeugte Logereignisse <code>system_log.fire_event</code> in Home Assistant aktivieren und <code>system_log_event</code> in der App unter <code>runtime_events</code> freigeben.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.116" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.116 · GitHub / ZIP</a></p><p><strong>0.1.115 · Hinweis am ioBroker-Dateiauslöser</strong></p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> blieben beim Import eines echten ioBroker-Blockly-Exports mit <code>onFile</code> das Dateimuster <code>ugso-115-*.txt</code> und der Dateinamenblock <code>onFile_data</code> im Antwortzweig erhalten. Der Hinweis erschien in der Importübersicht und direkt am Block. Er erklärt, wie eine HA-Automation mit Folder Watcher den Dateinamen aus <code>trigger.to_state.attributes.file</code> liest.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.115" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.115 · GitHub / ZIP</a></p><p><strong>0.1.114 · Hinweis zum alten ioBroker-GET-Block</strong></p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> blieben beim Import eines echten ioBroker-Blockly-Exports mit <code>request</code> die GET-URL und der Antwortzweig mit <code>result</code> erhalten. Der Hinweis erschien in der Importübersicht und direkt am Block. Er beschreibt den Wechsel zu „HTTP GET · HA REST“ und die Zuordnung von <code>result</code>, <code>response.statusCode</code> und <code>error</code> zu den Antwortblöcken. Der Test prüfte den Import und den Hinweis.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.114" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.114 · GitHub / ZIP</a></p><p><strong>0.1.113 · Hinweis am ioBroker-Block „Datei lesen“</strong></p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> lieferte die native Home-Assistant-Aktion <code>file.read_file</code> für die JSON-Testdatei <code>data.probe = 42</code>. Beim Import des echten ioBroker-Blockly-Exports in Blocks JS blieben der Dateiname und der verschachtelte <code>file_data</code>-Block im Antwortzweig erhalten. Der Hinweis erschien in der Importübersicht und direkt am Block. Er erklärt, wie ein HA-Skript den Inhalt über <code>response_variable</code> und <code>.data</code> weiterverarbeitet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.113" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.113 · GitHub / ZIP</a></p><p><strong>0.1.112 · Hinweis am ioBroker-Block „Datei schreiben“</strong></p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurde ein echter ioBroker-Blockly-Export mit <code>file_write</code> in Blocks JS importiert. Der Platzhalter behielt die Anschlüsse für Speicherobjekt, Dateiname und Inhalt. Der Hinweis erschien in der Importübersicht und direkt am Block. Er beschreibt, wie <code>notify.send_message</code> Text an eine fest konfigurierte Datei anhängt und wann für das ursprüngliche Schreibverhalten ein eigener Dienst nötig ist.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.112" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.112 · GitHub / ZIP</a></p><p><strong>0.1.111 · Hinweis am ioBroker-Dateiblock</strong></p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> blieb beim Import eines echten ioBroker-Blockly-Exports der Dateiname <code>ugso-111-probe.txt</code> erhalten. Der Hinweis erschien in der Importübersicht und direkt am Block. Er erklärt, dass <code>downloader.download_file</code> einen eigenen GET-Aufruf startet. Wer die bereits empfangene Antwort speichern und einen Dateipfad weiterverwenden möchte, benötigt dafür einen eingerichteten Dienst. Nach dem lokalen Neuaufbau zeigte die Studio-Kopfzeile in Chrome <code>0.1.111</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.111" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.111 · GitHub / ZIP</a></p><p><strong>0.1.110 · Hinweis zum HTTP-Antworttyp arraybuffer</strong></p><p>Der ioBroker-Blockly-Export mit <code>arraybuffer</code> bleibt beim Import als gekennzeichneter Platzhalter erhalten. Im Play-Kontrolltest mit dem HTTP-Block im Textmodus lieferte Home Assistant die vier Bytes <code>00 41 C3 A9</code> als <strong>drei Textzeichen</strong>. <code>byteLength</code> war <code>null</code>. Bei <code>00 41 FF 80</code> meldete Home Assistant einen Dekodierfehler. Blocks JS erhielt dabei keine Bytes. Der Hinweis am Block erklärt den möglichen Weg über einen Endpunkt, der die Binärdaten als <strong>Base64 in JSON</strong> liefert. Die Antwortverarbeitung muss entsprechend angepasst werden. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p>Im anschließenden Play-Test auf dem Testsystem PC (64) dekodierte eine JavaScript-Funktion in Blocks JS das Base64-Feld der JSON-Antwort zu den Bytes <code>00 41 FF 80</code>. Das Runtime-Protokoll zeigte die Bytefolge und die Länge <code>4</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.110" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.110 · GitHub / ZIP</a></p><p><strong>0.1.109 · Fehlerbehandlung für ungültige JSON-Antworten</strong></p><p>Im Live-Test per Play erreichten zwei ungültige JSON-Antworten den Fehlerzweig. Home Assistant meldete beim Dekodieren „Ungültige JSON-Antwort. Home Assistant konnte die Antwort nicht als JSON lesen.“ Der Status war <code>null</code>. Als Blocks JS den ungültigen Antworttext selbst dekodierte, meldete es „Ungültige JSON-Antwort.“ und behielt <strong>HTTP 200</strong>. Im selben Lauf lieferte die gültige Folgeanfrage <strong><code>42</code></strong>. Das Skript lief weiter. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.109" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.109 · GitHub / ZIP</a></p><p><strong>0.1.108 · HTTP-Antworttyp JSON beim ioBroker-Import</strong></p><p>Blocks JS übernimmt den Antworttyp <code>json</code> und stellt die Antwortdaten für den direkten Feldzugriff bereit. Im Live-Test per Play lieferten der unveränderte ioBroker-Blockly-Export mit „JSON nach Objekt“ und die angepasste XML-Testvariante mit <code>TYPE=json</code> und direktem Feldzugriff für <strong><code>result.value</code></strong> jeweils <strong><code>42</code></strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.108" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.108 · GitHub / ZIP</a></p><p><strong>0.1.107 · Berechnete HTTP-URLs beim ioBroker-Import</strong></p><p>Blocks JS erhält den URL-Ausdruck aus ioBroker. Der Host und der feste URL-Anfang werden im freigegebenen HA-REST-Befehl festgelegt. Den variablen Teil übergibt Blocks JS als <code>url_suffix</code>. Im GET-Live-Test per Play empfing der Testendpunkt <strong><code>garten &amp; 42</code></strong> als einzelnen Query-Wert und antwortete mit <strong>HTTP 200</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p>Im anschließenden <strong>POST-Live-Test per Play</strong> mit einem ioBroker-Blockly-Export empfing der Endpunkt in derselben Anfrage den berechneten Query-Wert <code>garten &amp; 42</code> und den JSON-Payload <code>{&quot;probe&quot;:42}</code>. Er antwortete mit <strong>HTTP 200</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.107" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.107 · GitHub / ZIP</a></p><p><strong>0.1.106 · Request-Header beim ioBroker-POST-Import</strong></p><p>Blocks JS übernimmt auch frei eingegebene Content-Type-Werte aus ioBroker-POST-Blöcken. Der importierte Wert steht im Block als Vorgabe für den HA-REST-Befehl. Im Live-Test per Play bestätigte der Testendpunkt <strong><code>Content-Type: application/vnd.ugso+json</code></strong> und <strong><code>Accept: application/json</code></strong>. Der POST lieferte HTTP 200 und übertrug den JSON-Wert <code>42</code>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.106" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.106 · GitHub / ZIP</a></p><p><strong>0.1.105 · HTTP-Fehlerbehandlung in Blocks JS</strong></p><p>Blocks JS übernimmt den ioBroker-Fehlerblock für HTTP-Aufrufe. In zwei Live-Läufen per Play protokollierte das importierte Skript zuerst <strong>HTTP 404</strong>. Beim zweiten Aufruf erreichte ein <strong>Verbindungsfehler</strong> den Fehlerzweig ohne HTTP-Status. Die Runtime blieb in beiden Fällen aktiv. In einem weiteren Live-Test per Play löste ein langsamer Testendpunkt einen <strong>HTTP-Timeout</strong> aus. Der Fehlerzweig lief ohne HTTP-Status (<code>null</code>), und das Skript lief weiter. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.105" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.105 · GitHub / ZIP</a></p><p><strong>0.1.104 · HTTP-Antwortheader in Blocks JS</strong></p><p>Blocks JS übernimmt ioBroker-Antwortheader. Die Namen werden kleingeschrieben, damit etwa <code>content-type</code> ausgelesen werden kann. Im Live-Test per Play lieferte der echte GET-Aufruf <strong><code>Content-Type: application/json</code></strong>. Das importierte Skript las den Header und protokollierte <code>application/json</code>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.104" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.104 · GitHub / ZIP</a></p><p><strong>0.1.103 · HTTP-POST-Import in Blocks JS</strong></p><p>Blocks JS übernimmt ioBroker-HTTP-POST mit JSON-Payload, Statusprüfung und Antwortauswertung. Im Live-Test per Play empfing der temporäre Endpunkt den Payload <code>{&quot;probe&quot;:42}</code> und antwortete mit <strong>Status 200</strong>. Das importierte Skript las das JSON-Feld <code>value</code> und protokollierte <strong>42</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.103" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.103 · GitHub / ZIP</a></p><p><strong>0.1.102 · HTTP-GET-Import in Blocks JS</strong></p><p>Blocks JS übernimmt ioBroker-HTTP-GET mit Statusprüfung und JSON-Auswertung. Für die Ausführung wird dem Block ein freigegebener HA-REST-Befehl zugeordnet. Im Live-Test lieferte der echte HTTP-Aufruf <strong>Status 200</strong>. Das importierte Skript las das JSON-Feld <code>value</code> und protokollierte <strong>42</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.102" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.102 · GitHub / ZIP</a></p><p><strong>0.1.101 · Hinweis am importierten exec-Block</strong></p><p>Der vorhandene ioBroker-Testexport enthält am <code>exec</code>-Block den Vergleich „aktuelle Zeit vor 12:00“. Im Test erschien der Hinweis sowohl in der Importübersicht als auch direkt am Blockly-Platzhalter. Der Vergleich blieb erhalten. Der Hinweis erklärt, wie er an „falls“ angeschlossen und die gewünschte HA-Aktion unter „mache“ eingefügt wird. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.101" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.101 · GitHub / ZIP</a></p><h3 id="ha-logic-studio-pro-0-1-81–0-1-100" tabindex="-1">HA Logic Studio Pro 0.1.81–0.1.100 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-81–0-1-100" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.81–0.1.100&quot;">​</a></h3><p><strong>0.1.100 · Template-Bedingung in Rules</strong></p><p>Im Expertenmodus lässt sich eine Jinja-Bedingung hinzufügen. Rules exportiert sie als native Home-Assistant-Template-Bedingung. Im Live-Test schaltete DANN den Testhelfer ein und SONST schaltete ihn wieder aus. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.100" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.100 · GitHub / ZIP</a></p><p><strong>0.1.99 · Strukturprüfung für verschachtelte HA-YAML-Zweige</strong></p><p>HA-YAML markiert Strukturfehler in verschachtelten <code>choose</code>-Zweigen an der betroffenen Zeile. Auf dem Testsystem landete die Markierung in <strong>Zeile 10</strong>. Der Blueprint-Export enthielt bytegleich alle 159 Bytes einschließlich Eingaben und Zusatzfeld. JavaScript und TypeScript verwiesen im Testlauf jeweils auf <strong>Zeile 2</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.99" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.99 · GitHub / ZIP</a></p><p><strong>0.1.98 · Aufbewahrung der Runtime-Protokolle</strong></p><p>Pro Projekt bleiben Runtime-Protokolle bis zu <strong>30 Tage</strong> erhalten. Das Limit liegt bei <strong>64 KiB</strong> und <strong>100 Einträgen</strong>. Die Bereinigung erfasst auch gestoppte Projekte. Im Live-Test wurde ein 31 Tage alter Eintrag entfernt und eine übergroße Protokolldatei von <strong>84.240 auf 65.430 Byte</strong> gekürzt. Der neu erzeugte Runtime-Eintrag war nach dem Neustart der App im gestoppten Testprojekt weiterhin abrufbar. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.98" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.98 · GitHub / ZIP</a></p><p><strong>0.1.97 · Blocks-JS-Austausch und Funktionsplan-Speicher</strong></p><p>In Blocks JS zeigt die Entitäts-ID-Ansicht am ausgewählten importierten Block auch die ursprüngliche ioBroker-ID. Mit den echten Exporten <code>test33.xml</code> und <code>test33.js</code> wurden die Importhinweise geprüft. Der ausgewählte Aktualisierungsblock samt angeschlossenem Wert ließ sich als JSON-Text und als Datei in einen eigenen Entwurf übernehmen.</p><p>Im Funktionsplan blieben Zähler <code>1</code> und Merker <code>true</code> beim erneuten Start des gespeicherten Plans nach einem App-Neustart erhalten. Automatisierte Tests mit dem Runtime-Runner prüfen den Neustart mit bereits aktivem Eingang und das Verwerfen alter Werte nach geänderter Verdrahtung. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.97" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.97 · GitHub / ZIP</a></p><p><strong>0.1.96 · Rules-Gruppen und Blocks-A-Zielkataloge</strong></p><p><strong>Rules.</strong> Verschachtelte UND-, ODER- und NICHT-Gruppen lassen sich mit Trigger-IDs kombinieren. Im HA-Live-Test führte <code>first</code> den DANN-Zweig aus. Die innere Bedingung blockierte <code>second</code>, sodass SONST lief. Der Trace bestätigte das Warten auf einen Zustand, den Skriptparameter <code>42</code>, die Benachrichtigung und das Abschlussereignis. Bereich und Label übernahmen dieselbe Testentität. Bei geänderter Zuordnung lässt sich die Entitätsliste durch erneutes Auswählen aktualisieren.</p><p><strong>Blocks A.</strong> Der Testbereich, das Testlabel, das Loopback-Testgerät und die Testetage ließen sich jeweils in der Zielauswahl übernehmen. Der erzeugte HA-YAML-Entwurf enthielt die passenden IDs unter <code>area_id</code>, <code>label_id</code>, <code>device_id</code> und <code>floor_id</code>. Die Testobjekte wurden anschließend entfernt. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.96" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.96 · GitHub / ZIP</a></p><p><strong>0.1.95 · Rules-Bedingung „Ausgelöst durch“</strong></p><p>Auslöser können eine optionale <strong>Trigger-ID</strong> erhalten. Die Bedingung <strong>Ausgelöst durch</strong> verweist auf eine dieser IDs und wird als <code>condition: trigger</code> in HA-YAML ausgegeben. Im Live-Test führte das HA-Ereignis mit der Trigger-ID <code>first</code> den <strong>DANN</strong>-Zweig aus. Das Ereignis mit <code>second</code> führte den <strong>SONST</strong>-Zweig aus. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.95" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.95 · GitHub / ZIP</a></p><p><strong>0.1.94 · HA-YAML mit Automation oder Skript verknüpfen</strong></p><p>Über <strong>HA-Eintrag verknüpfen</strong> lässt sich einem YAML-Projekt eine bestehende Automation oder ein Skript zuordnen. Nach dem Speichern zeigt der Editor den Status und, sofern verfügbar, den letzten Auslösezeitpunkt. Auf dem Testsystem PC (64) ließ sich die Testautomation deaktivieren, aktivieren und mit Bedingungsprüfung auslösen. Das Testskript ließ sich starten und stoppen. Die Verknüpfungen blieben nach dem Neuladen erhalten. <strong>Abbrechen</strong> stellte die gespeicherte Zuordnung wieder her. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.94" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.94 · GitHub / ZIP</a></p><p><strong>0.1.93 · YAML-Rückexport mit Blueprint-Instanzen</strong></p><p>Beim YAML-Rückexport bleiben die ursprünglichen Inhalte erhalten, einschließlich zusätzlicher Felder, Kommentare, YAML-Tags sowie Blueprint-Pfad und Eingaben. Auf dem Testsystem PC (64) wurden die Flur-Testdatei mit zusätzlichen verschachtelten Feldern und eine Blueprint-Instanz importiert und erneut exportiert. Der SHA-256-Vergleich bestätigte für beide Dateien einen bytegleichen Rückexport. Chrome beließ beide Dateien beim Test als <code>.crdownload</code>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.93" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.93 · GitHub / ZIP</a></p><p><strong>0.1.92 · Entitäten und Aktionen am YAML-Cursor einfügen</strong></p><p>Mit <strong>Entität einfügen</strong> und <strong>HA-Aktion einfügen</strong> lässt sich die gewählte ID am Cursor einsetzen. Ist Text markiert, ersetzt die ID die Auswahl. Im Test mit der Flur-Automation wurden <code>sun.sun</code> und <code>homeassistant.turn_off</code> exakt an den vorgesehenen Cursorpositionen eingefügt. Alle drei <code>choose</code>-Zweige blieben sichtbar. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.92" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.92 · GitHub / ZIP</a></p><p><strong>0.1.91 · HA-Katalogprüfung im YAML-Editor</strong></p><p>Der YAML-Editor markiert unbekannte Entitäten, ungültige Zielfelder und von Home Assistant nicht gelistete Aktionsfelder direkt im Code. Dynamische Templates werden bei der Katalogprüfung ausgelassen. Im Test der Flur-Automation erschien die Markierung für eine unbekannte Entität in <strong>Zeile 28</strong> und für ein ungültiges Feld von <code>light.turn_on</code> in <strong>Zeile 45</strong>. Nach der Korrektur verschwanden beide Testmarkierungen. Alle drei <code>choose</code>-Zweige blieben sichtbar. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.91" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.91 · GitHub / ZIP</a></p><p><strong>0.1.90 · Syntaxfarben und Fehlerzeilen in HA-YAML</strong></p><p>Der HA-YAML-Editor zeigt Syntaxfarben und Zeilennummern. Fehler werden an der betroffenen Stelle im Code und am Zeilenrand markiert. Im Test der Flur-Automation auf dem Testsystem PC (64) markierte der Editor einen absichtlich doppelten <code>mode</code>-Schlüssel in <strong>Zeile 79</strong>. Nach der Korrektur verschwand die Markierung und alle drei <code>choose</code>-Zweige blieben sichtbar. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.90" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.90 · GitHub / ZIP</a></p><p><strong>0.1.89 · JSON-Import in HA-YAML</strong></p><p>Über <strong>JSON importieren</strong> eine JSON-Datei auswählen oder den Inhalt einfügen. Die geprüfte Konfiguration öffnet sich als YAML-Entwurf und wird erst mit <strong>Speichern</strong> übernommen.</p><p>Auf dem Testsystem PC (64) wurden <code>Flur.automation.json</code> aus Logic Studio Pro und <code>flur test.flode.json</code> aus FLODE über den Dateidialog importiert. Beide ergaben inhaltlich dasselbe YAML und behielten alle drei <code>choose</code>-Zweige für Umschalten, Einschalten und Ausschalten. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.89" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.89 · GitHub / ZIP</a></p><p><strong>0.1.88 · Grafische HA-YAML-Vorschau</strong></p><p>Die Karte „Auswählen“ sitzt mittig zwischen den Zweigen und zeigt die beschrifteten Anschlüsse dauerhaft an. Auf dem Testsystem PC (64) waren in der Flur-Automation <strong>Option 1</strong>, <strong>Option 2</strong>, <strong>Option 3</strong> und <strong>Standard</strong> sichtbar. Alle sieben Verbindungen wurden angezeigt, die Karten überlappten sich nicht und der YAML-Text blieb beim Ansichtswechsel unverändert.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.88" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.88 · GitHub / ZIP</a></p><p><strong>0.1.87 · React Flow</strong></p><p>Die grafische HA-YAML-Vorschau nutzt React Flow mit feinem Punktraster, kompakten Karten, Minimap, Zoom, Verschieben und „Alles einpassen“. <code>choose</code> erscheint als eine Karte mit beschrifteten Ausgängen pro Option und einem Standardausgang. Die Ansicht dient der Visualisierung. Änderungen werden im YAML-Editor vorgenommen.</p><p>Auf dem Testsystem PC (64) wurden alle drei Ausgänge der Flur-Automation geprüft. Die Karten überlappten auch bei langen Entitäts-IDs nicht. Der YAML-Text war nach dem Wechsel zurück in den Editor identisch.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.87" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.87 · GitHub / ZIP</a></p><p><strong>0.1.86 · Grafische HA-YAML-Vorschau</strong></p><p>Die grafische Vorschau stellt Auslöser, Bedingungen und Aktionen als Karten dar. Bei einer <code>choose</code>-Aktion zeigt sie die einzelnen Zweige mit ihren Bedingungen und Aktionen.</p><p>Auf dem Testsystem PC (64) zeigte die Flur-Automation alle vier Auslöser und alle drei <code>choose</code>-Zweige. Beide heruntergeladenen YAML-Dateien waren bytegleich. Der Vergleich mit der Eingabe bestätigte alle Felder, darunter Trigger-IDs, Geräte-ID und Ereignisoptionen, Zielentitäten, Sonnenversätze und <code>mode: restart</code>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.86" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.86 · GitHub / ZIP</a></p><p><strong>0.1.85 · Zeitfenster und Wochentage in Rules</strong></p><p>In <strong>Zeitfenster und Wochentage</strong> lassen sich Startzeit, Endzeit und einzelne Wochentage kombinieren. Auch eine Auswahl nur nach Wochentagen ist möglich. Der Export nutzt die native HA-Bedingung <code>condition: time</code>.</p><p>Im Live-Test lief die Automation nur bei passender Uhrzeit und passendem Wochentag. Außerhalb des Zeitfensters und bei einem abweichenden Wochentag blieben die jeweiligen Testhelfer aus. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.85" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.85 · GitHub / ZIP</a></p><p><strong>0.1.84 · HA-Startauslöser in Rules</strong></p><p>Der Auslöser <strong>Home Assistant gestartet</strong> steht in der Rules-Palette und im Assistenten zur Verfügung. Der YAML-Export erzeugt <code>trigger: homeassistant</code> mit <code>event: start</code>.</p><p>Im Live-Test schaltete die Automation den Testhelfer nach einem Neustart von Home Assistant Core ein. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.84" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.84 · GitHub / ZIP</a></p><p><strong>0.1.83 · MQTT-Auslöser in Rules</strong></p><p>Der Rules-Assistent bietet <strong>MQTT-Nachricht</strong> mit einem Pflichtfeld für das Topic und einem optionalen Payload-Filter. Ohne Filter löst jede Nachricht auf dem Topic aus.</p><p>Im Live-Test löste die Automation genau einmal aus, als Topic und Payload übereinstimmten. Ein falsches Topic und ein abweichender Payload lösten keinen Lauf aus. Der Home-Assistant-Trace bestätigte die Zähleraktion. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.83" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.83 · GitHub / ZIP</a></p><p><strong>0.1.82</strong></p><p>Der Rules-Assistent bietet <strong>Uhrzeit aus Helfer</strong> an. Wähle einen Home-Assistant-Helfer vom Typ <code>input_datetime</code> mit Uhrzeit. Der YAML-Export verwendet <code>trigger: time</code> und trägt die Entitäts-ID unter <code>at</code> ein. Wenn du die Uhrzeit am Helfer änderst, übernimmt Home Assistant den neuen Termin.</p><p>Im Live-Test auf dem Testsystem PC (64) wurde der Helfer von 17:27:27 auf 17:27:56 umgestellt. Zum ursprünglichen Termin blieb die Auslösung aus. Der Home-Assistant-Trace bestätigt die Ausführung um <strong>17:27:56</strong>. <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a></p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.82" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.82 · GitHub / ZIP</a></p><p><strong>0.1.81</strong></p><p>Der Rules-Assistent bietet Sonnenaufgang und Sonnenuntergang als Auslöser an. Der optionale Zeitversatz wird in Minuten eingegeben. Negative Werte lösen vor dem Sonnenereignis aus, positive danach.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurde der YAML-Export in der installierten Version geprüft und validiert. 30 Minuten vor Sonnenaufgang ergaben <code>event: sunrise</code> und <code>offset: -1800</code>. 15 Minuten nach Sonnenuntergang ergaben <code>event: sunset</code> und <code>offset: 900</code>. Die YAML-Werte sind in Sekunden angegeben.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.81" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.81 · GitHub / ZIP</a></p><h3 id="ha-logic-studio-pro-0-1-61–0-1-80" tabindex="-1">HA Logic Studio Pro 0.1.61–0.1.80 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-61–0-1-80" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.61–0.1.80&quot;">​</a></h3><details class="details custom-block"><summary>Versionsverlauf</summary><p><strong>0.1.80</strong></p><p>Der Rules-Assistent bietet den Auslöser <strong>Zahlenschwelle</strong> mit „Über“, „Unter“ oder beiden Grenzen für einen Bereich. Attribut und Mindestdauer sind optional. Der YAML-Export verwendet den nativen Home-Assistant-Auslöser <code>numeric_state</code>.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> erzeugte der installierte Rules-Editor für „Über 50“ den Eintrag <code>above: 50</code>. Im Live-Test des erzeugten YAMLs löste die Automation bei 51 einmal aus. Bei 65 und 49 blieb der Zähler bei 1. Erst beim erneuten Überschreiten mit 52 stieg der Zähler auf 2.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.80" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.80 · GitHub / ZIP</a></p><p><strong>0.1.79</strong></p><p>Die Importvorschau in Blocks JS zeigt pro Block, welche Home-Assistant-Entität zugeordnet werden muss oder welche Codeanpassung noch nötig ist. Feste ioBroker-IDs lassen sich direkt in der Vorschau einer HA-Entität zuordnen.</p><p>Mit dem Originalexport <code>test33.xml</code> wurden auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> der Zustandstrigger einem Sensor und der Schreibblock einem Zahlenhelfer zugeordnet. Im Testlauf simulierte Blocks JS Schreibvorgänge mit den Werten <code>21</code> und <code>20</code>.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.79" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.79 · GitHub / ZIP</a></p><p><strong>0.1.78</strong></p><p>Unter <strong>Globale Skripte</strong> können JavaScript- und TypeScript-Projekte gespeicherte Skripte aus dem gleichnamigen Ordner auswählen. Der Dialog zeigt den Aufrufpfad für benannte Funktionen, die mit <code>export function</code> freigegeben wurden, etwa <code>shared.script_43.twice(21)</code>.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> rief je ein allgemeines JavaScript- und TypeScript-Projekt dieselbe globale TypeScript-Funktion auf. Testlauf und Runtime lieferten in beiden Projekten <code>42</code>. TypeScript markierte ein Argument mit falschem Typ in Zeile 2. Die Auswahl blieb nach dem Neuladen erhalten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.78" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.78 · GitHub / ZIP</a></p><p><strong>0.1.77</strong></p><p><strong>Typen prüfen</strong> prüft den TypeScript-Code und die Typen der Skript-API. Der Editor markiert fehlerhafte Zeilen. Ein Klick auf die Zeilennummer im Protokoll springt zur ursprünglichen Stelle. Testlauf und Runtime prüfen die Typen vor der Ausführung.</p><p>Auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurden zwei absichtlich erzeugte Typfehler in Zeile 2 und 3 markiert. Nach der Korrektur lief der Testlauf erfolgreich. Beim Start des fehlerhaften Skripts meldete die Runtime Zeile 2.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.77" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.77 · GitHub / ZIP</a></p><p><strong>0.1.76</strong></p><p>In den JavaScript- und TypeScript-Editoren schlägt <code>ha.</code> Methoden der Skript-API vor. Die Liste zeigt Parameter und Rückgabetypen. Beim Schreiben eines Aufrufs hebt der Editor den aktuellen Parameter hervor.</p><p>Im Chrome-Test auf dem <a href="/sammlung/testsysteme#testsystem-pc">Testsystem PC (64)</a> wurden die Tastaturauswahl in beiden Editoren und die Signaturen für <code>ha.readState</code>, <code>ha.callAction</code> und <code>ha.pause</code> geprüft.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.76" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.76 · GitHub / ZIP</a></p><p><strong>0.1.75</strong></p><p>Das Protokoll zeigt im Testlauf und in der Runtime bei zuordenbaren Fehlern die ursprüngliche JavaScript- oder TypeScript-Zeile an. Ein Klick auf die Zeilennummer springt im Editor zur betroffenen Stelle.</p><p>Auf dem <strong>Testsystem PC (64)</strong> meldeten beide Ausführungsarten den absichtlich ausgelösten Fehler in <strong>JavaScript-Zeile 3</strong> und <strong>TypeScript-Zeile 5</strong>. Die TypeScript-Zeilennummer blieb korrekt, obwohl beim Übersetzen eine Typdeklaration wegfiel.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.75" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.75 · GitHub / ZIP</a></p><p><strong>0.1.74</strong></p><p>Logic Studio Pro speichert die letzten 100 Runtime-Protokolleinträge pro Benutzer und Projekt. Auf dem Testsystem PC (64) blieb ein Eintrag nach einem Neustart der App mit demselben Zeitstempel abrufbar. Das Skript war dabei gestoppt. In einem anderen Projekt erschien der Eintrag nicht.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.74" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.74 · GitHub / ZIP</a></p><p><strong>0.1.73</strong></p><p>Beim Runtime-Test auf dem Testsystem PC (64) mit 0.1.72 startete der zweite Auslöser, bevor der erste abgeschlossen war. Beide liefen bis zum Ende. Ein gezielter Fehler stoppte das betroffene Skript. Das andere Skript verarbeitete anschließend einen dritten Auslöser erfolgreich.</p><p>Nach dem lokalen Update auf 0.1.73 wurde auf dem Testsystem PC (64) geprüft, dass die Home-Assistant-App-Seite „Experimentell“ und der Studio-Header „Interner Test“ nicht mehr anzeigen. Die drei Testprojekte wurden gelöscht.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.73" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.73 · GitHub / ZIP</a></p><p><strong>0.1.72</strong></p><p>Blocks JS übernimmt ioBroker-Skriptnachrichten mit Antwort und berechneten Zieladressen. Die Importvorschau zeigt am jeweiligen Block, welche Empfangsadresse und Antwortverarbeitung zu prüfen sind.</p><p>Auf dem Testsystem PC (64) setzte ein laufendes Blocks-JS-Skript die Zieladresse aus zwei Textteilen zusammen. Das zweite Skript protokollierte den Empfang, und der Antwortblock im Sender wurde ausgeführt. Danach wurden beide Testprojekte gelöscht und die temporäre Freigabe für <code>logic_studio_script_message</code> wieder entfernt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.72" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.72 · GitHub / ZIP</a></p><p><strong>0.1.71</strong></p><p>Der Schalter „Expertenmodus“ im Projektmenü speichert die Auswahl pro Home-Assistant-Benutzer. Er blendet erweiterte Werkzeuge ein, darunter Quelltext und Skript-API in JavaScript, Import und Codeausgabe in Blocks JS sowie Diagnose und Ausführung im Funktionsplan. Speichern, Abbrechen, Testlauf und Play sind in den dafür vorgesehenen Editoren direkt erreichbar.</p><p>Nach einem Vollbackup auf dem Testsystem PC (64) wurden diese drei Editoren geprüft. Die Auswahl blieb nach dem Neuladen erhalten. Anschließend wurde die ursprüngliche Einstellung wiederhergestellt und nach erneutem Neuladen bestätigt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.71" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.71 · GitHub / ZIP</a></p><p><strong>0.1.70</strong></p><p>Benutzerdefinierte Ordner lassen sich über das Stiftsymbol im Projektbaum umbenennen. Auf dem Testsystem PC (64) habe ich nach einem Vollbackup die Projektbaum-Exporte vor dem Umbenennen und nach dem Neuladen verglichen. Ordner-ID, Projektzuordnungen und Reihenfolge der beiden Projekte blieben erhalten. Danach habe ich den ursprünglichen Namen wiederhergestellt und nach erneutem Neuladen bestätigt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.70" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.70 · GitHub / ZIP</a></p><p><strong>0.1.69</strong></p><p>Der Rules-Assistent übernimmt einen Sprachwechsel im geöffneten Editor. Nach einem Vollbackup auf dem Testsystem PC (64) wurden im Chrome-Tabletformat (820 × 1180 px) beim Wechsel <strong>DE → EN → FR → DE</strong> Titel, Schritte und Auslöser in der jeweils gewählten Sprache angezeigt. Die Studio-Oberfläche und die App-Verwaltung in Home Assistant zeigten beide <strong>0.1.69</strong>. Der Server liest die angezeigte Version jetzt aus den Paketdaten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.69" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.69 · GitHub / ZIP</a></p><p><strong>0.1.68</strong></p><p>Der YAML-Export lädt die Datei direkt aus dem Editor herunter. Beim Doppeltest auf dem Testsystem PC (64) wurden zwei vollständige, bytegleiche YAML-Dateien erzeugt. Chrome meldete beim zweiten Export <strong>Unsicherer Download blockiert</strong>. Nach der manuellen Bestätigung mit <strong>Behalten</strong> lag auch die zweite Datei vollständig im Downloadordner.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.68" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.68 · GitHub / ZIP</a></p><p><strong>0.1.67</strong></p><p>Aktuelles öffentliches Testupdate. Vor dem Update ein Vollbackup erstellen und zuerst auf einem Testsystem prüfen.</p><p>„Datenpunkt vorhanden?“ und „Objekt-ID“ behalten beim Import die ioBroker-ID. Ordne sie im jeweiligen Block ausdrücklich einer HA-Entität zu. Beim Import einer JavaScript-Datei erkennt Blocks JS eingebettete Blockly-Daten auch dann, wenn weitere Kommentare folgen.</p><p>Unter <strong>Nötige Codeanpassungen</strong> erklärt die Importvorschau, wie sich nicht unterstützte Blöcke wie <code>exec</code> ersetzen lassen. Auf dem Testsystem PC (64) wurden nach einem Vollbackup XML- und JavaScript-Testdateien importiert und die neuen Zuordnungsfelder im Editor geprüft.</p><p><strong>Wiederverbindung nach Core-Neustart</strong></p><p>Auf dem Testsystem PC (64) wurde vor dem Test ein Vollbackup erstellt. Nach dem Neustart von Home Assistant Core stellte die Runtime die Verbindung 31 Sekunden nach der Trennung wieder her. Derselbe JavaScript-Skriptlauf empfing anschließend den Wechsel des Testhelfers von <code>off</code> auf <code>on</code> und das benutzerdefinierte HA-Ereignis <code>logic_studio_runtime_test</code> samt Testdaten.</p><p><strong>Ordnerwechsel und Reihenfolge nach Neuladen</strong></p><p>Auf dem Testsystem PC (64) wurden nach einem Vollbackup zwei Testskripte per Drag-and-drop in einen anderen Ordner verschoben. Nach dem Speichern der Sortierung und dem Neuladen von Logic Studio Pro waren beide Skripte weiterhin im Zielordner und standen in der gespeicherten Reihenfolge.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.67" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.67 · GitHub / ZIP</a></p><p><strong>0.1.66</strong></p><p>Aktiviere im Funktionsplan <strong>Zähler und Merker speichern</strong> und speichere das Projekt. CTU, CTD, CTUD, RS und SR können ihre Werte nach einem App-Neustart wiederherstellen.</p><p>Der Blocks-JS-Importbericht weist berechnete ioBroker-IDs separat aus. Ordne im importierten Block unter <strong>ID-Zuordnung (JSON)</strong> jede mögliche ioBroker-ID einer HA-Entität zu.</p><p>Auf dem Testsystem PC (64) behielten der CTU-Zähler und der RS-Merker nach einem App-Neustart die Werte <code>1</code> und <code>true</code>.</p><p>Im Live-Test auf dem Testsystem PC (64) berechnete das importierte Blocks-JS-Skript die ioBroker-ID <code>zigbee.0.sensor</code>. Über <strong>ID-Zuordnung (JSON)</strong> las es den HA-Testhelfer <code>input_boolean.logic_studio_runtime_test</code>. Zwei Starts über <strong>Play</strong> ergaben im Runtime-Protokoll <code>false</code> bei ausgeschaltetem und <code>true</code> bei eingeschaltetem Helfer.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.66" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.66 · GitHub / ZIP</a></p><p><strong>0.1.65</strong></p><p><strong>Autostart, Simulation und ioBroker-Import</strong></p><p>JavaScript, TypeScript und Funktionspläne können beim Start der App ausgeführt werden. Speichere dafür die Option <strong>Beim Start der App ausführen</strong> im Projekt. Die Simulation bietet Haltepunkte und Einzelschritt. Beim automatischen Anordnen bleiben angeheftete Bausteine stehen. Blocks JS zeigt beim ioBroker-Import nicht unterstützte Blöcke und feste IDs zur Zuordnung.</p><p>Auf dem Testsystem PC (64) startete das gespeicherte JavaScript-Testprojekt nach einem Neustart der App automatisch. Geprüft wurden außerdem ein Haltepunkt mit Einzelschritt sowie die ioBroker-Importvorschau mit einer festen ID.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.65" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.65 · GitHub / ZIP</a></p><p><strong>Erweiterte Rules und Live-Test auf dem Testsystem PC (64)</strong></p><p>Zustandsauslöser unterstützen Von/Nach, ein Attribut und eine Mindestdauer. Bedingungen prüfen Zustände und Attribute sowie numerische Grenzen. DANN und SONST unterstützen einen HA-Aktionswähler mit JSON-Parametern und separate Verzögerungsschritte.</p><p>Der Editor und der Aktionswähler wurden lokal im Browser geprüft. Nach einem Vollbackup lief die erzeugte YAML direkt in Home Assistant auf dem Testsystem PC (64). Ein kurzer Impuls löste nichts aus. Nach drei Sekunden Zustandsdauer lief DANN. Ein Wechsel des Anzeigenamens löste SONST aus. Beide Traces bestätigten zwei Sekunden Verzögerung und den erwarteten Textwert. Die Testautomation und beide Helfer wurden entfernt.</p><p>Die neuen Bausteine werden als HA-YAML ausgegeben. Rules → JS meldet, wenn ein Baustein die Konvertierung verhindert.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.62" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.62 · GitHub / ZIP</a></p><p><strong>YAML-Export und Live-Test auf dem Testsystem PC (64)</strong></p><p>Der Rules-Export schützt Zustände wie <code>on</code> und <code>off</code> vor der Umwandlung in YAML-Wahrheitswerte. Die korrigierte Automation wurde direkt in Home Assistant auf dem Testsystem PC (64) mit Testhelfern ausgeführt.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Auslöser</th><th>Bedingung</th><th>Ergebnis laut HA-Trace</th></tr></thead><tbody><tr><td>Zustandswechsel</td><td>ODER erfüllt</td><td>Beide DANN-Aktionen</td></tr><tr><td>Zustandswechsel</td><td>UND nicht erfüllt</td><td>Beide SONST-Aktionen</td></tr><tr><td>HA-Ereignis</td><td>NICHT erfüllt</td><td>Beide DANN-Aktionen</td></tr><tr><td>Uhrzeit 20:26</td><td>NICHT nicht erfüllt</td><td>Beide SONST-Aktionen</td></tr></tbody></table></div><p>Vor dem Test wurde ein Vollbackup erstellt. Die Testautomation und alle drei Testhelfer wurden danach entfernt.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.61" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.61 · GitHub / ZIP</a></p></details><h3 id="ha-logic-studio-pro-0-1-41–0-1-60" tabindex="-1">HA Logic Studio Pro 0.1.41–0.1.60 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-41–0-1-60" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.41–0.1.60&quot;">​</a></h3><details class="details custom-block"><summary>Versionsverlauf</summary><p><strong>Rules: kompakte Leiste und mehrere Auslöser</strong></p><p>Links zeigt der Editor eine kompakte Liste mit Icons. Eine Regel kann Zustandswechsel, tägliche Uhrzeit und HA-Ereignisse kombinieren. Bedingungen unterstützen UND, ODER und NICHT. In DANN und SONST laufen mehrere Aktionen in der eingetragenen Reihenfolge.</p><p>Auf dem Testsystem PC (64) wurde eine bestehende Regel mit drei Auslösern, zwei Bedingungen und zwei Aktionen pro Zweig geprüft. Die YAML-Vorschau zeigte die erwartete Struktur. Im Studio-Testlauf führten alle drei simulierten Auslöser bei erfüllter ODER-Bedingung beide DANN-Aktionen aus. Bei nicht erfüllter UND-Bedingung liefen beide SONST-Aktionen in der festgelegten Reihenfolge. Es wurden keine echten Geräte geschaltet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.60" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.60 · GitHub / ZIP</a></p><p><img src="'+r+'" alt="Rules-Editor auf dem Testsystem PC (64) mit kompakter Leiste und beiden Aktionszweigen"></p><p><strong>Regeln mit dem Assistenten erstellen</strong></p><p>Wähle <strong>Regeln → Assistent</strong>. Der Dialog führt durch <strong>Auslöser → Bedingungen → Aktionen → Übersicht</strong>. Eine Regel kann auf einen Zustandswechsel, eine tägliche Uhrzeit in der HA-Zeitzone oder ein HA-Ereignis reagieren. Bedingungen und der SONST-Zweig sind optional. In der Übersicht siehst du die YAML-Vorschau. <strong>Übernehmen</strong> überträgt den Entwurf in den Editor; erst <strong>Speichern</strong> sichert ihn dauerhaft. Bestehende Regeln lassen sich weiterhin bearbeiten und als JavaScript oder HA-YAML öffnen.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.59" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.59 · GitHub / ZIP</a></p><p>Am 12. November 2026 wurden alle drei Auslöser direkt in Home Assistant auf dem Testsystem PC (64) geprüft. Ein Zustandswechsel von Aus auf Ein, die tägliche Uhrzeit um 19:38 Uhr (HA-Ortszeit) und das Ereignis <code>rules_live_0159_event</code> schalteten den Testausgang jeweils auf Ein. Vor dem Test wurde ein Vollbackup erstellt. Anschließend wurden die drei Testautomationen und beide Testhelfer entfernt.</p><p><img src="'+n+`" alt="Home Assistant zeigt die letzte Ausführung aller drei Rules-Testautomationen und den eingeschalteten Testausgang"></p><p><strong>Was seit 0.1.12 neu ist</strong></p><ul><li><strong>Projektbaum und Editoren:</strong> Projekte und Ordner werden pro HA-Benutzer serverseitig gespeichert. Vorhandene Browserprojekte können beim ersten Start aus dem bisherigen Browser übernommen werden. JavaScript und TypeScript haben Syntaxfarben, Zeilennummern und eigene Werkzeugleisten. Icons und Farben stimmen zwischen Projektauswahl, Baum und Filtern überein. Blocks A und Blocks JS haben getrennte Filter. Die automatisch bemessene Projektspalte bleibt per Anfasser verstellbar.</li><li><strong>Blocks A und Blocks JS:</strong> Blocks A nutzt den integrierten Katalog von Blocks for HA. Blocks JS hat eine eigene JavaScript-Palette. Blocks A exportiert HA-Automationen als YAML. Blocks JS erzeugt JavaScript für Testlauf und Runtime. Beim ioBroker-Import bleiben unbekannte Blöcke als Platzhalter sichtbar und verhindern die Codeausgabe, bis sie ersetzt sind. ioBroker-Objekt-IDs durch passende HA-Entitäts-IDs ersetzen.</li><li><strong>Funktionsplan:</strong> Simulation, Zeitschritt von einer Sekunde und Zurücksetzen liegen als Icons in der oberen Leiste. Ausgabeformat und Vorschau sind rechts angeordnet. Verbindungen lassen sich am Zieleingang umhängen, Signalwerte erscheinen direkt am Eingang.</li><li><strong>Server-Runtime:</strong> Play startet JavaScript, transpiliertes TypeScript oder Blocks JS auf dem HA-Server. Stopp und Neustart sind im Editor verfügbar. Status und Runtime-Protokoll bleiben beim Browserwechsel abrufbar. Der separate <strong>Testlauf</strong> verwendet simulierte Zustände und Ereignisse. HA-YAML-Skripte und -Automationen werden exportiert und anschließend in Home Assistant ausgeführt.</li></ul><p><strong>Live-Runtime einrichten</strong></p><p>In <strong>Einstellungen → Apps → HA Logic Studio Pro → Konfiguration</strong> die benötigten Einträge setzen, speichern und die App neu starten. Die Listen sind anfangs leer. Beispiel für einen eigens angelegten Testhelfer:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_read_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_write_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.logic_studio_runtime_test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_runtime_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Eine Schreibfreigabe erlaubt auch das Lesen. <code>ha.readState</code> und <code>ha.readAttribute</code> liefern die zuletzt von HA bestätigten Werte. <code>ha.onState</code>, <code>ha.onAttribute</code> und <code>ha.onEvent</code> reagieren auf freigegebene Änderungen und Ereignisse. <code>ha.callAction</code> unterstützt Schaltaktionen, Werte für Zahlen-, Text- und Auswahlhelfer sowie Taster mit genau einem freigegebenen Ziel. <code>ha.schedule</code> verarbeitet Zeitmuster und feste Uhrzeiten mit optionalen Wochentagen in der HA-Zeitzone.</p><p>Nach einem App-Neustart müssen Skripte erneut gestartet werden. Bei einer Verbindungsunterbrechung oder abgelehnten Aktion hält die Runtime das Skript an und protokolliert den Fehler. Astro-Auslöser und automatische Wiederverbindung sind offen.</p><p><strong>Geprüft auf dem Testsystem PC (64) mit HA 2026.11.1:</strong> Live-Zustand und Attribut gelesen, Testhelfer per Zeitplan eingeschaltet und per echtem HA-Ereignis ausgeschaltet. Beide Zustandswechsel wurden gemeldet. Ein importierter Blocks-JS-Zeitplan lief alle zwei Sekunden. Zuvor wurden Start, Stopp, Neustart und der Weiterlauf nach Verlassen der Studio-Seite mit JavaScript und TypeScript geprüft.</p><p><strong>Skripte und Automationen steuern</strong></p><p>Unter <strong>Blocks JS → System</strong> wählst du mit <strong>Skript oder Automation auswählen</strong> eine Home-Assistant-Entität aus und verbindest den Block mit <strong>Steuern</strong>. Skripte lassen sich starten oder stoppen. Automationen lassen sich aktivieren, deaktivieren oder einmal auslösen. Beim Auslösen ist <strong>Bedingungen prüfen</strong> standardmäßig aktiv. Wenn du die Option abwählst, überspringt Home Assistant die Bedingungen. Für die Live-Ausführung muss die Zielentität unter <code>runtime_write_entities</code> freigegeben sein.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.58" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.58 · GitHub und ZIP</a></p><p><strong>Funktionen und ioBroker-Import</strong></p><p>Unter <strong>Blocks JS → Funktionen</strong> gibt es zwei JavaScript-Funktionsblöcke mit und ohne Rückgabewert. Über das Zahnrad legst du Parameter fest. Über <strong>…</strong> bearbeitest du den Code. Nach dem Anlegen einer Definition erscheint der passende Aufrufblock in der Palette.</p><p>Der ioBroker-Import übernimmt Definitionen, Aufrufe, Parameter und JavaScript-Code. Passe ioBroker-spezifische API-Aufrufe an die HA-Runtime an und ordne importierte Objekt-IDs explizit HA-Entitäten zu.</p><p><strong>Verlauf abfragen</strong></p><p>Unter <strong>Blocks JS → Sendto → Verlauf abfragen</strong> liest du aufgezeichnete Zustände aus dem HA-Recorder. Ohne Zeitraum gilt der aktuelle Tag in der HA-Zeitzone. Der Ergebnisblock liefert Einträge mit Zeitstempel und Wert. Beim ioBroker-Import bleiben Zeitraum, Aggregation, Schrittweite und Anzahl erhalten.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.57" target="_blank" rel="noreferrer">HA Logic Studio Pro 0.1.57 · GitHub und ZIP</a></p></details><h3 id="ha-logic-studio-pro-0-1-21–0-1-40" tabindex="-1">HA Logic Studio Pro 0.1.21–0.1.40 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-21–0-1-40" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.21–0.1.40&quot;">​</a></h3><details class="details custom-block"><summary>Versionsverlauf</summary><p><strong>0.1.29 · Manuelles Speichern und Blocks-Editoren</strong></p><p>Alle Editoren übernehmen Änderungen erst mit <strong>Speichern</strong>. <strong>Abbrechen</strong> lädt den letzten gespeicherten Stand oder verwirft ein neues Projekt. Bei ungespeicherten Änderungen sind <strong>Play</strong> und <strong>Neustart</strong> gesperrt. Ein laufendes Skript lässt sich weiterhin stoppen. Blocks A öffnet die Entitätsauswahl direkt am Blockfeld. Blocks JS bietet eine an ioBroker orientierte Palette mit HA-Entitäten, HA-Aktionen und Auslösern ohne Jinja.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.29" target="_blank" rel="noreferrer">Testupdate und ZIP</a></p><p><strong>0.1.28 · Übersetzungen in den Editoren</strong></p><p>Version <strong>0.1.28</strong> ergänzt die Übersetzungen für Regeln, Blocks A, Blocks JS, JavaScript, TypeScript und HA-YAML. Die Sprachwahl gilt auch für den Funktionsplan. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.28" target="_blank" rel="noreferrer">Testupdate und ZIP</a></p><p>Auf dem Testsystem PC (64) wurden die Werkzeugleisten von Funktionsplan, Regeln, Blocks A, Blocks JS, JavaScript, TypeScript, HA-Automation und HA-Skript im Browser in allen drei Sprachen geprüft. Zusätzlich wurde der französische Dialog für Codebeispiele geprüft.</p><p>Für die Installation im App-Store des UGSo-Sammelrepositories <strong>HA Logic Studio Pro</strong> auswählen. Bei einer bestehenden GitHub-Installation nach Updates suchen und <strong>HA Logic Studio Pro → Aktualisieren</strong> wählen. Mit <strong>DE</strong>, <strong>EN</strong> und <strong>FR</strong> oben in der Projektleiste wechselt die Sprache der Editoren.</p><p><strong>0.1.26 · FBD Runtime</strong></p><p>Funktionsplan direkt über <strong>Play</strong> auf dem HA-Server starten. <strong>Automatisch</strong> reagiert auf Änderungen der freigegebenen Zustände und Attribute; <strong>Fester Zyklus</strong> wertet den Plan alle 100 bis 60.000 ms aus. Simulation und YAML-Ausgabe bleiben separat. <strong>Speichern</strong> übernimmt den Entwurf, <strong>Abbrechen</strong> lädt den letzten gespeicherten Stand. Die Werkzeugleiste ist in DE/EN/FR verfügbar.</p><p>Auf dem Testsystem PC (64) schaltete der Automatikstart den Testhelfer ein; der 200-ms-Zyklus schaltete ihn wieder aus. Stopp und das Verwerfen einer ungespeicherten Änderung wurden ebenfalls geprüft. Die Reaktion auf Eingangsänderungen wurde zusätzlich lokal für beide Betriebsarten getestet.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.26" target="_blank" rel="noreferrer">GitHub-Testupdate und ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_logic_studio_pro" target="_blank" rel="noreferrer">App im Sammelrepository</a></p></details><h3 id="ha-logic-studio-pro-0-1-1–0-1-20" tabindex="-1">HA Logic Studio Pro 0.1.1–0.1.20 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-1–0-1-20" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.1–0.1.20&quot;">​</a></h3><details class="details custom-block"><summary>Versionsverlauf</summary><p>Die ersten öffentlichen Testversionen führten die eigenständige App mit Funktionsplan, HA-Import und React Flow ein.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases?q=ha-logic-studio-pro+0.1.&amp;expanded=true" target="_blank" rel="noreferrer">HA Logic Studio Pro · GitHub</a></p></details><h2 id="testinstallation-aus-github" tabindex="-1">Testinstallation aus GitHub <a class="header-anchor" href="#testinstallation-aus-github" aria-label="Permalink to &quot;Testinstallation aus GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Repository in Home Assistant hinzufügen"></a></p><ol><li>In <strong>Einstellungen → Apps → App-Store → Repositorys</strong> die folgende Adresse eintragen. Ist „UGSo HA Apps“ schon eingerichtet, nur nach Updates suchen.</li><li><strong>UGSo Logic Studio</strong> auswählen und installieren. Falls experimentelle Apps ausgeblendet sind, im HA-Profil den erweiterten Modus aktivieren.</li><li>Starten und die Benutzeroberfläche öffnen. Unterstützt werden <strong>HA OS/Supervised</strong>, <strong>amd64 und aarch64</strong>. Der erste Container-Build kann einige Minuten dauern. Dies ist kein HACS-/Marketplace-Frontend-Paket.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Vorhandene lokale Testinstallation erhalten:</strong> GitHub- und lokale App haben verschiedene Repository-IDs und getrennte Daten. Den alten Plan über <strong>Projekt</strong> als JSON exportieren und in der GitHub-App über <strong>Öffnen</strong> importieren. Es gibt keine automatische Migration oder Deinstallation. Projekt und Paletteinstellungen der jeweiligen App bleiben unter <code>/data</code> gespeichert.</p><p><strong>Bestehende GitHub-App aktualisieren:</strong> Vorher sichern, in der App-Verwaltung nach Updates suchen und <strong>UGSo Logic Studio → Aktualisieren</strong> wählen. Die App bleibt installiert; <code>/data</code>, Entity-IDs und bestehende Pläne werden nicht ersetzt. Nicht deinstallieren oder die App-ID wechseln. Auf dem Testsystem PC (64) blieben Originalplan, Favoriten, zuletzt benutzte Bausteine und eingeklappte Bereiche nach dem Update erhalten.</p><h2 id="sprache-werkzeugleiste-und-dokumentation" tabindex="-1">Sprache, Werkzeugleiste und Dokumentation <a class="header-anchor" href="#sprache-werkzeugleiste-und-dokumentation" aria-label="Permalink to &quot;Sprache, Werkzeugleiste und Dokumentation&quot;">​</a></h2><p>Oben <strong>Sprache → Deutsch / English / Français</strong> wählen. Menüs, Bausteinbeschreibungen, Entitätsauswahl sowie Import-/Exportdialoge wechseln ohne Neuladen. Die Auswahl wird mit den Browser-/App-Einstellungen gespeichert. <strong>Eigene Namen, Entitäts-IDs, Werte, Anschlussbezeichnungen und erzeugter YAML-/JavaScript-Code werden nicht übersetzt.</strong></p><p><strong>Dokumentation</strong> rechts zeigt die tatsächlich unterstützten Tastenkürzel und bei ausgewähltem Baustein dessen Beschreibung sowie Ein-/Ausgänge. <strong>Strg+Z / Strg+Y</strong>: Rückgängig/Wiederholen; <strong>Entf</strong>: Auswahl löschen; <strong>Esc</strong>: Verbindung abbrechen/Menü schließen. Anschlüsse lassen sich mit Tab und Enter/Leertaste auswählen und verbinden. Debugger-Befehle des ioBroker-Referenzeditors werden nicht als verfügbare Funktionen dargestellt.</p><p>Die Werkzeugleiste gruppiert <strong>Rückgängig/Wiederholen → Projekt → Simulation → Ausgabe</strong>. Die drei Simulationsbuttons sind gleich groß und einzeln erkennbar. Das Projektmenü enthält zusätzlich <strong>Neues Projekt</strong> und <strong>Beispiel laden</strong>. Die Entitätsauswahl öffnet über das Icon <strong>neben HA-Entity-ID</strong> in den Eigenschaften von STATE_IN/STATE_OUT; der bisherige obere Auswahlbutton entfällt.</p><p><img src="`+s+'" alt="Deutsche Dokumentationsansicht auf dem Testsystem PC (64) mit unverändertem Plan"></p><p><img src="'+i+'" alt="Englische Dokumentationsansicht desselben Plans auf dem Testsystem PC (64)"></p><p><img src="'+o+'" alt="Französische Dokumentationsansicht desselben Plans auf dem Testsystem PC (64)"></p><h2 id="zwei-arten-von-planen" tabindex="-1">Zwei Arten von Plänen <a class="header-anchor" href="#zwei-arten-von-planen" aria-label="Permalink to &quot;Zwei Arten von Plänen&quot;">​</a></h2><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Plan</th><th>Zweck und Ausgabe</th></tr></thead><tbody><tr><td>Wertplan</td><td>Typisierte Ein-/Ausgänge, Logik, Mathematik, Auswahl sowie Speicher, Flanken, Timer und Zähler. 33 implementierte Typen; weitere Referenztypen sind als Vorlagen gekennzeichnet. Ausgabe als HA-Automation, HA-Skript oder JavaScript-Funktion mit Host-Schnittstelle.</td></tr><tr><td>Nativer HA-Ablauf</td><td>Automationen, Skripte und Blueprints importieren und als verschachtelte Bausteine bearbeiten. 53 zusätzliche HA-Typen für Auslöser, Bedingungen, Zweige, Schleifen, Warteaktionen, Variablen und Blueprint-Eingaben. Ausgabe ausschließlich als native HA-YAML.</td></tr></tbody></table></div><p>Wertpläne können mit Demo-/Momentaufnahmewerten simuliert werden. Persistente Wertbausteine benötigen die dokumentierten HA-Texthelfer bzw. einen JavaScript-Speicher-Host. Native HA-Abläufe werden im Editor weder ausgeführt noch automatisch in JavaScript umgerechnet. Die JavaScript-Ausgabe ist kein ioBroker-Skript.</p><h2 id="verbindungen-ziehen-und-miniubersicht" tabindex="-1">Verbindungen ziehen und Miniübersicht <a class="header-anchor" href="#verbindungen-ziehen-und-miniubersicht" aria-label="Permalink to &quot;Verbindungen ziehen und Miniübersicht&quot;">​</a></h2><p>Am farbigen Anschluss die Maustaste gedrückt halten, zum passenden Gegenanschluss ziehen und loslassen. Der Cursor wird zum Kreuz; eine Leitungsvorschau folgt der Maus. Passende Ziele werden grün, unpassende oder belegte Eingänge rot markiert. Auch vom Eingang zurück zum Ausgang ziehen ist möglich. <strong>Esc</strong> oder Loslassen auf freier Fläche bricht ab; <strong>Rückgängig</strong> nimmt eine erstellte Leitung zurück.</p><p><strong>BOOL verbindet nur mit BOOL.</strong> Gleiche Signaltypen passen zueinander; <code>INT → REAL</code> ist zusätzlich erlaubt. Explizite <code>ANY</code>-Anschlüsse sind universell. Zahlen und Texte werden nicht stillschweigend zu BOOL umgedeutet. Pro Eingang ist genau eine Leitung erlaubt; falsche Typen, gleiche Anschlussseiten, Selbstverbindungen und Rückkopplungen werden abgewiesen. Eine Fehlermeldung erklärt den Grund. Für die Tastatur Ausgang per Tab/Enter auswählen, anschließend Eingang und Enter.</p><p><img src="'+a+'" alt="Auf dem Testsystem PC (64) erfolgreich mit der Maus verbundene BOOL-Anschlüsse"></p><p><img src="'+d+'" alt="STRING nach BOOL wird mit verständlichem Typfehler abgewiesen"></p><p>Rechts unten zeigt die <strong>MiniMap</strong> farbige Bausteinpositionen und den sichtbaren Ausschnitt. In der MiniMap ziehen zum Navigieren und das Mausrad zum Zoomen verwenden. Auf der freien Zeichenfläche ziehen verschiebt den Ausschnitt; <strong>+/−</strong> ändern den Zoom, <strong>Alles anzeigen</strong> passt alle Bausteine ein. Bausteine am Kopf verschieben. Der Herkunftslink <strong>React Flow</strong> bleibt unten rechts sichtbar. Seit 0.1.8 läuft die Bibliothek tatsächlich im Editor; Fachlogik, Typprüfung und Exporte bleiben eigenständige Logic-Studio-Funktionen.</p><p><img src="'+u+'" alt="React-Flow-Zeichenfläche mit erhaltenem Originalplan und MiniMap auf dem Testsystem PC (64)"></p><p><img src="'+l+'" alt="Lokaler React-Flow-Test mit typisierten Bausteinen"></p><p>Die folgenden Bilder dokumentieren zusätzlich die vorherigen Tests mit 0.1.7.</p><p><img src="'+g+'" alt="Miniübersicht mit Bausteinpositionen und sichtbarem Ausschnitt auf dem Testsystem PC (64)"></p><h2 id="import-und-bearbeitung" tabindex="-1">Import und Bearbeitung <a class="header-anchor" href="#import-und-bearbeitung" aria-label="Permalink to &quot;Import und Bearbeitung&quot;">​</a></h2><p><strong>HA importieren</strong> öffnen, Automationen/Skripte/Blueprints auswählen und <strong>Aus HA einlesen</strong>, eine YAML-/JSON-Datei oder eingefügten Text verwenden. Eintrag und Vorschau prüfen, dann <strong>Import übernehmen</strong>. Vorher den eigenen Plan als JSON sichern; zusätzlich entstehen Projekt- und Quelldateisicherungen.</p><p>Der HA-Konfigurationsordner ist <strong>schreibgeschützt</strong> eingebunden. Gelesen werden <code>automations.yaml</code>, <code>scripts.yaml</code> und Blueprint-Dateien. Vor dem Parsen kopiert die App Quellen unter <code>/data/ha-source-backups/&lt;Zeitstempel&gt;/</code> mit ursprünglichem Namen. <code>secrets.yaml</code> wird nicht geöffnet; <code>!secret</code> und <code>!include</code> bleiben unaufgelöst. Bei ausgelagerten Include-Dateien die tatsächliche Datei selbst importieren.</p><p>Orange <strong>FLOW</strong>-Leitungen bilden Reihenfolge und Zweige ab: Zweigausgang → <strong>DO</strong>, anschließend <strong>NEXT → DO</strong>. Gelbe <strong>VALUE/REF</strong>-Leitungen zeigen Blueprint-Parameter und deren <code>!input</code>-Verwendung. Eigenschaften enthalten HA-Konfiguration und Zweigpfade als JSON. Parameter-/Feldschlüssel müssen eindeutig sein. Unbekannte Abschnitte bleiben als <strong>YAML_ORIGINAL</strong> erhalten; fehlende Verbindungen können den Export sperren.</p><p><img src="'+c+'" alt="Importvorschau vorhandener HA-Blueprints"></p><p>Das <strong>⋮-Menü</strong> jedes Bausteins bietet <strong>Eigenschaften, Duplizieren und Löschen</strong>. Duplizieren übernimmt Eigenschaften ohne Leitungen. Löschen entfernt zugehörige Leitungen; <strong>Rückgängig</strong> stellt sie wieder her. Suche, Favoriten und zuletzt benutzte Bausteine erleichtern die Auswahl.</p><p><img src="'+p+'" alt="Drei-Punkte-Menü im Funktionsplan"></p><h2 id="prufstand-und-grenzen" tabindex="-1">Prüfstand und Grenzen <a class="header-anchor" href="#prufstand-und-grenzen" aria-label="Permalink to &quot;Prüfstand und Grenzen&quot;">​</a></h2><p><strong>0.1.12 auf dem Testsystem PC (64) / HA Core 2026.10.4:</strong> Nach Vollbackup die lokale App von 0.1.8 aktualisiert. DE/EN/FR, Dokumentationsansicht und reale Entitätsauswahl erfolgreich geprüft. Französisch blieb nach Browser-Neuladen, App-Neustart und erneutem Laden des gespeicherten App-Projekts erhalten; abschließend wieder Deutsch eingestellt. Der Vergleich der Projektdateien zeigt <strong>nur die neue Versionsnummer</strong>, alle fünf Bausteine, drei Verbindungen, Namen, Werte und Positionen sind identisch. Der erzeugte YAML-Code ist in EN und FR identisch. Keine Geräte geschaltet. <strong>31 Node- und neun Python-Tests</strong> bestanden. Die folgenden älteren Berichte bleiben als Historie erhalten.</p><p><img src="'+h+'" alt="Deutsch nach erfolgreichem App-Neustart auf dem Testsystem PC (64)"></p><p><strong>0.1.8 auf dem Testsystem PC (64) / HA Core 2026.10.4:</strong> Bestehende lokale App nach Vollbackup aktualisiert. BOOL-Verbindungen per Maus, STRING→BOOL-Abweisung, belegte Eingänge, Verschieben/Rückgängig, Duplizieren, Zoom und MiniMap bestanden. Die Entitätsauswahl liest HA-Entitäten; ein verschachteltes Skript mit If/Then/Else, Delay und Stop wurde importiert und strukturerhaltend ausgegeben. Danach Originalplan wiederhergestellt und nach Neuladen verglichen: <strong>alle IDs, Positionen, Parameter und drei Leitungen unverändert</strong>, ebenso Favoriten, zuletzt benutzt und eingeklappte Kategorien. Keine Geräte geschaltet. Docker-Build und Container-HTTP-Test erfolgreich; <strong>29 Node- und acht Python-Tests</strong> bestanden. Bilder zeigen die deutsche Oberfläche. Hell-/Dunkel-Wechsel wurde in diesem Schritt nicht erneut manuell geprüft.</p><p>Der Funktionsstand <strong>0.1.5</strong> wurde auf <strong>Testsystem PC (64) / HA Core 2026.10.4</strong> geprüft: echter Blueprint-Import, Automation-/Skript-/Blueprint-Beispiele, inhaltlich gleiche YAML-Ausgabe und Menüaktionen. <strong>0.1.6</strong> ist dessen erste öffentliche Paketierung. 22 Node- und acht Python-Tests prüfen unter anderem Export, Persistenz, verschachtelte Abläufe und sicheren Quelldateiimport; die GitHub-Prüfung baut zusätzlich den Container.</p><p><strong>0.1.7 auf dem Testsystem PC (64) / HA Core 2026.10.4:</strong> Echter Maus-Ziehtest für BOOL → BOOL und die Gegenrichtung bestanden. STRING → BOOL und ein bereits belegter Eingang wurden abgewiesen. Miniübersicht, Klicknavigation und Pos1 geprüft. Nach dem Test wurde der Originalplan wiederhergestellt und mit der Sicherung verglichen: <strong>fünf Bausteine, drei Leitungen und alle Paletteinstellungen erhalten</strong>, einschließlich nach dem lokalen Update auf 0.1.7. Vorher vollständiges HA-Backup und separate Plan-/Einstellungssicherung; keine Geräte geschaltet. Aktuell bestehen <strong>26 Node- und acht Python-Tests</strong>. Bilder zeigen die deutsche Oberfläche.</p><p>Keine vollständige HA-Semantikprüfung im Editor: Ziele, Templates und Selektoren in HA kontrollieren. Kommentare, YAML-Anker und Formatierung werden nicht originalgetreu rekonstruiert. Importgrenzen: <strong>1 MB, 200 Bausteine, 500 Leitungen</strong>, begrenzte Verschachtelung und bis zu 250 Blueprint-Dateien in üblichen Ordnern. Regler, Kalender und eigene Unterpläne sind teilweise noch Vorlagen.</p><p>Für lokale Tests das Release-ZIP vollständig entpacken, Python 3.10+ und die Pakete aus <code>requirements.txt</code> installieren; unter Windows danach <strong>Start-Demo.cmd</strong> starten. <code>http://127.0.0.1:4180/</code> zeigt Demo-Entitäten ohne HA-Verbindung. Das ZIP enthält außerdem <code>addon/logic_studio/</code> für lokale App-Installationen.</p><p>Fehler bitte mit Versionen, Architektur und einem kleinen anonymisierten Beispiel <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">auf GitHub melden</a>. Keine Zugangsdaten, persönlichen Automationen oder Vollbackups veröffentlichen. Weitere Anleitungen und Prüfbericht liegen im Paket. Lizenz: MIT; Herkunft der übernommenen Block-Metadaten siehe <code>THIRD-PARTY.txt</code>.</p>',226)])])}const E=m(A,[["render",S]]);export{D as __pageData,E as default};
